        raise ValueError("Training and validation identities must be disjoint.")
    xs, ys = transform(train_rows, scaler)
    vx, vy = transform(validation_rows, scaler)
    parameters = initial_parameters(hidden_units, seed)
    generator = random.Random(seed)
    def measure(epoch):
        train = restore([forward(parameters, x, hidden_units)[0] for x in xs], scaler)
        validation = restore([forward(parameters, x, hidden_units)[0] for x in vx], scaler)
        return {"epoch": epoch,
                "train_mae": metrics([r["value_k"] for r in train_rows], train)["mae"],
                "validation_mae": metrics([r["value_k"] for r in validation_rows], validation)["mae"]}
    history = [measure(0)]
    best_parameters = parameters[:]
    best_mae, best_epoch, stale = history[0]["validation_mae"], 0, 0
    started = time.process_time()
    reason, completed = "max_epochs", 0
    for epoch in range(1, epochs+1):
        order = list(range(len(xs)));generator.shuffle(order)
        timed_out = False
        for start in range(0, len(order), batch_size):
            if time.process_time()-started >= cpu_seconds:
                timed_out = True;break
            ids = order[start:start+batch_size]
            _, gradient = loss_gradient(parameters,[xs[i] for i in ids],[ys[i] for i in ids],hidden_units,l2)
            parameters = [p-learning_rate*g for p,g in zip(parameters,gradient)]
        if timed_out:
            reason = "cpu_budget";break
        completed = epoch
        point = measure(epoch);history.append(point)
        if point["validation_mae"] < best_mae-1e-6:
            best_mae, best_epoch, best_parameters, stale = point["validation_mae"], epoch, parameters[:], 0
        else:
            stale += 1
            if stale >= patience:
                reason = "validation_patience";break
    return {"parameters": best_parameters,"hidden_units":hidden_units,"best_epoch":best_epoch,
            "completed_epochs":completed,"stop_reason":reason,"history":history,
            "cpu_seconds":time.process_time()-started,"seed":seed,"batch_size":batch_size,"l2":l2}



def select_model(validation_scores):
    names=("median","linear","neural")
    if set(validation_scores)!=set(names) or any(
        not number(validation_scores[name]["mae"]) or validation_scores[name]["mae"]<0
        for name in names
    ):
