    rows = matrix(values)
    if not 1 <= k <= min(16, len(set(map(tuple, rows)))):
        raise ValueError('k must fit distinct rows')
    if not 1 <= max_iter <= 100 or not math.isfinite(tolerance) or tolerance < 0:
